(function($){'use strict';$(document).ready(function(){if($('.malisafi-city-list-container').length===0){return;}const $container=$('.malisafi-city-list-container');const $searchInput=$('#city-search-input');const $cityItems=$('.city-item');const $noResults=$('.city-no-results');const $totalCities=$('.total-cities');const totalCount=$cityItems.length;function filterCities(searchTerm){searchTerm=searchTerm.toLowerCase().trim();let visibleCount=0;if(searchTerm===''){$cityItems.show();visibleCount=totalCount;$noResults.hide();}else{$cityItems.each(function(){const $item=$(this);const cityName=$item.data('city-name');if(cityName.includes(searchTerm)){$item.show();visibleCount++;}else{$item.hide();}});if(visibleCount===0){$noResults.show();}else{$noResults.hide();}}$totalCities.text(visibleCount);}$searchInput.on('input',function(){const searchTerm=$(this).val();filterCities(searchTerm);});$searchInput.on('keydown',function(e){if(e.key==='Escape'||e.keyCode===27){$(this).val('');filterCities('');}});$('.city-link').on('click',function(e){const cityName=$(this).closest('.city-item').data('city-name');if(typeof gtag!=='undefined'){gtag('event','city_click',{'city_name':cityName});}$(this).addClass('loading');});$('.city-item').on('mouseenter',function(){$(this).addClass('hovered');}).on('mouseleave',function(){$(this).removeClass('hovered');});$searchInput.on('keydown',function(e){const $visibleItems=$('.city-item:visible');if($visibleItems.length===0)return;if(e.key==='ArrowDown'){e.preventDefault();$visibleItems.first().find('.city-link').focus();}});$('.city-link').on('keydown',function(e){const $currentItem=$(this).closest('.city-item');const $allVisibleItems=$('.city-item:visible');const currentIndex=$allVisibleItems.index($currentItem);if(e.key==='ArrowDown'){e.preventDefault();const $nextItem=$allVisibleItems.eq(currentIndex+1);if($nextItem.length){$nextItem.find('.city-link').focus();}}else if(e.key==='ArrowUp'){e.preventDefault();if(currentIndex>0){const $prevItem=$allVisibleItems.eq(currentIndex-1);$prevItem.find('.city-link').focus();}else{$searchInput.focus();}}});function adjustGrid(){const $cityList=$('.city-list-grid');if($cityList.length===0)return;const containerWidth=$container.width();let columns=parseInt($cityList.data('columns'))||4;if(containerWidth<480){columns=1;}else if(containerWidth<768){columns=2;}else if(containerWidth<1024){columns=3;}$cityList.css('--columns',columns);}adjustGrid();$(window).on('resize',debounce(adjustGrid,250));function debounce(func,wait){let timeout;return function executedFunction(...args){const later=()=>{clearTimeout(timeout);func(...args);};clearTimeout(timeout);timeout=setTimeout(later,wait);};}$('.city-link').on('click',function(e){if(window.location.pathname===malisafiCityList.searchPageUrl){e.preventDefault();const url=$(this).attr('href');$('html,body').animate({scrollTop:0},400,function(){window.location.href=url;});}});function initAnimations(){const observer=new IntersectionObserver((entries)=>{entries.forEach((entry,index)=>{if(entry.isIntersecting){setTimeout(()=>{entry.target.classList.add('animate-in');},index * 50);observer.unobserve(entry.target);}});},{threshold:0.1});$cityItems.each(function(){observer.observe(this);});}if('IntersectionObserver' in window){initAnimations();}else{$cityItems.addClass('animate-in');}});})(jQuery);